 @Test public void actualServicePublishesFile()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();byte[] bytes=new byte[128000];new java.util.Random(5).nextBytes(bytes);ServerSocket server=new ServerSocket(0,5,InetAddress.getByName("127.0.0.1"));AtomicBoolean stop=new AtomicBoolean();Thread t=new Thread(()->{while(!stop.get())try(Socket sock=server.accept()){BufferedReader r=new BufferedReader(new InputStreamReader(sock.getInputStream()));String first=r.readLine(),line;while((line=r.readLine())!=null&&!line.isEmpty()){}OutputStream out=sock.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: "+bytes.length+"\r\nETag: \"test\"\r\nConnection: close\r\n\r\n").getBytes());if(first!=null&&first.startsWith("GET"))out.write(bytes);out.flush();}catch(Exception ignored){}});t.start();Store.settings(c).edit().putBoolean("http",true).putBoolean("wifi",false).putBoolean("battery",false).putInt("mode",1).commit();String url="http://127.0.0.1:"+server.getLocalPort()+"/sample.bin";Store.Job job=new Store.Job(url,new HttpEngine.Info("xdownload-test.bin","application/octet-stream",bytes.length,"","",true),"");Store.get(c).add(job);try(ActivityScenario<MainActivity> a=ActivityScenario.launch(MainActivity.class)){a.onActivity(v->TransferService.command(v,"start",job.id));long until=android.os.SystemClock.elapsedRealtime()+30000;while(android.os.SystemClock.elapsedRealtime()<until){synchronized(Store.get(c)){if(job.state.equals("complete")||job.state.equals("error"))break;}Thread.sleep(100);}assertEquals(job.error,"complete",job.state);assertEquals(bytes.length,job.done);assertEquals(64,job.sha.length());try(InputStream in=c.getContentResolver().openInputStream(Uri.parse(job.uri));ByteArrayOutputStream out=new ByteArrayOutputStream()){assertNotNull(in);byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);assertArrayEquals(bytes,out.toByteArray());}}finally{stop.set(true);server.close();t.join(2000);if(!job.uri.isEmpty())c.getContentResolver().delete(Uri.parse(job.uri),null,null);c.stopService(new Intent(c,TransferService.class));Store.settings(c).edit().clear().commit();}}
 @Test public void nativeMp3Encoder()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();File input=new File(c.getCacheDir(),"sample.wav"),out=new File(c.getCacheDir(),"encoded.mp3");try{try(InputStream in=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("sample.wav");OutputStream o=new FileOutputStream(input)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)o.write(b,0,n);}ExportActivity.encodeMp3(c,input,out);assertTrue(out.length()>100);android.media.MediaExtractor ex=new android.media.MediaExtractor();try{ex.setDataSource(out.getAbsolutePath());assertEquals("audio/mpeg",ex.getTrackFormat(0).getString(android.media.MediaFormat.KEY_MIME));}finally{ex.release();}}finally{input.delete();out.delete();}}
 @Test public void mergeTwoAudioClips()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();File in=new File(c.getCacheDir(),"merge.wav"),out=new File(c.getCacheDir(),"merged.m4a");out.delete();try{try(InputStream input=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("sample.wav");OutputStream o=new FileOutputStream(in)){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1)o.write(b,0,n);}java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<Throwable> error=new java.util.concurrent.atomic.AtomicReference<>();java.util.concurrent.atomic.AtomicReference<androidx.media3.transformer.Transformer> transformer=new java.util.concurrent.atomic.AtomicReference<>();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{try{androidx.media3.transformer.Transformer tr=new androidx.media3.transformer.Transformer.Builder(c).setAudioMimeType(androidx.media3.common.MimeTypes.AUDIO_AAC).addListener(new androidx.media3.transformer.Transformer.Listener(){@Override public void onCompleted(androidx.media3.transformer.Composition x,androidx.media3.transformer.ExportResult r){latch.countDown();}@Override public void onError(androidx.media3.transformer.Composition x,androidx.media3.transformer.ExportResult r,androidx.media3.transformer.ExportException e){error.set(e);latch.countDown();}}).build();transformer.set(tr);tr.start(ExportActivity.mergeComposition(Uri.fromFile(in),Uri.fromFile(in),true),out.getAbsolutePath());}catch(Throwable x){error.set(x);latch.countDown();}});try{assertTrue("Merge timed out",latch.await(60,java.util.concurrent.TimeUnit.SECONDS));if(error.get()!=null)throw new AssertionError("Merge failed",error.get());assertTrue(out.length()>100);android.media.MediaMetadataRetriever mm=new android.media.MediaMetadataRetriever();try{mm.setDataSource(out.getAbsolutePath());long duration=Long.parseLong(mm.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION));assertTrue("Expected four seconds: "+duration,duration>=3800&&duration<=4300);}finally{mm.release();}}finally{InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{if(transformer.get()!=null)transformer.get().cancel();});}}finally{in.delete();out.delete();}}
 @Test public void formatSelectionAndShareRegistration()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();org.json.JSONObject json=new org.json.JSONObject("{\"title\":\"Test video\",\"duration\":10,\"formats\":[{\"format_id\":\"v720\",\"height\":720,\"ext\":\"mp4\",\"vcodec\":\"avc1\",\"acodec\":\"none\",\"filesize\":1000000},{\"format_id\":\"a128\",\"ext\":\"m4a\",\"vcodec\":\"none\",\"acodec\":\"aac\",\"abr\":128,\"filesize\":160000},{\"format_id\":\"drm\",\"ext\":\"mp4\",\"height\":2160,\"vcodec\":\"avc1\",\"acodec\":\"aac\",\"has_drm\":true}]}");MediaEngine.Result result=MediaEngine.parse(json);assertTrue(result.choices.stream().anyMatch(x->x.selector.equals("v720+a128")&&x.size==1160000&&x.estimated&&!x.audio));assertTrue(result.choices.stream().anyMatch(x->x.ext.equals("mp3")&&x.audio&&MediaEngine.mp3Rate(x)==320));assertTrue(result.choices.stream().anyMatch(x->x.ext.equals("mp3")&&MediaEngine.mp3Rate(x)==192));assertFalse(result.choices.stream().anyMatch(x->x.selector.contains("drm")));MediaEngine.Result wav=MediaEngine.parse(new org.json.JSONObject("{\"title\":\"WAV\",\"formats\":[{\"format_id\":\"wav\",\"ext\":\"wav\",\"vcodec\":\"none\",\"acodec\":\"none\"}]}"));assertTrue(wav.choices.stream().anyMatch(x->x.audio&&!x.mp3&&x.ext.equals("wav")));Intent share=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"https://example.org/file.mp4").setPackage(c.getPackageName());assertNotNull(share.resolveActivity(c.getPackageManager()));}
