 static final class FixtureServer implements AutoCloseable{
  final File dir;final ServerSocket socket;final java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(8);final Thread accept;volatile boolean dead;final java.util.concurrent.atomic.AtomicInteger gets=new java.util.concurrent.atomic.AtomicInteger();
  FixtureServer(File dir)throws Exception{this.dir=dir;socket=new ServerSocket(0,12,InetAddress.getByName("127.0.0.1"));accept=new Thread(()->{while(!dead)try{Socket client=socket.accept();pool.execute(()->serve(client));}catch(Exception ignored){}});accept.start();}
  String url(String path){return "http://127.0.0.1:"+socket.getLocalPort()+"/"+path;}
  void serve(Socket client){try(Socket s=client){s.setSoTimeout(10000);BufferedReader reader=new BufferedReader(new InputStreamReader(s.getInputStream()));String first=reader.readLine(),line,range="";if(first==null)return;for(int i=0;i<100&&(line=reader.readLine())!=null&&!line.isEmpty();i++)if(line.toLowerCase(java.util.Locale.ROOT).startsWith("range:"))range=line.substring(6).trim();String[] fields=first.split(" ");if(fields.length<2)return;String path=Uri.parse(fields[1]).getPath();File f=new File(dir,path.startsWith("/")?path.substring(1):path);OutputStream out=s.getOutputStream();if(!f.isFile()||!f.getCanonicalPath().startsWith(dir.getCanonicalPath()+File.separator)){out.write("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".getBytes());return;}long size=f.length(),start=0,end=size-1;boolean partial=false;if(range.matches("bytes=\\d+-\\d*")){String[] x=range.substring(6).split("-", -1);start=Long.parseLong(x[0]);if(!x[1].isEmpty())end=Math.min(end,Long.parseLong(x[1]));partial=true;}if(start>end){out.write(("HTTP/1.1 416 Range Not Satisfiable\r\nContent-Range: bytes */"+size+"\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").getBytes());return;}String name=f.getName(),mime=name.endsWith(".m3u8")?"application/vnd.apple.mpegurl":name.endsWith(".mpd")?"application/dash+xml":name.endsWith(".ts")?"video/mp2t":name.endsWith(".m4s")?"video/iso.segment":name.endsWith(".mp4")?"video/mp4":"application/octet-stream";out.write(("HTTP/1.1 "+(partial?"206 Partial Content":"200 OK")+"\r\nContent-Type: "+mime+"\r\nContent-Length: "+(end-start+1)+"\r\nAccept-Ranges: bytes\r\n"+(partial?"Content-Range: bytes "+start+"-"+end+"/"+size+"\r\n":"")+"Connection: close\r\n\r\n").getBytes());if(fields[0].equals("GET")){gets.incrementAndGet();try(RandomAccessFile in=new RandomAccessFile(f,"r")){in.seek(start);long left=end-start+1;byte[] b=new byte[32768];while(left>0){int n=in.read(b,0,(int)Math.min(left,b.length));if(n<0)break;out.write(b,0,n);left-=n;}}}out.flush();}catch(Exception ignored){}}
  public void close()throws IOException{dead=true;socket.close();pool.shutdownNow();try{accept.join(2000);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
 }
